private fun phosphor(name: String, paths: List<String>): ImageVector =
    ImageVector.Builder(name = "gear.$name", defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 256f, viewportHeight = 256f)
        .apply { paths.forEach { d -> addPath(pathData = addPathNodes(d), fill = SolidColor(Color.Black)) } }
        .build()
